'use strict';

// Frozen legacy LUMP bytes, big-endian uint32 encoded as base64.
// Captured with assembler.js from f592986a^ (before unresolved CALL rejection),
// using the sources embedded in these artifacts and the existing LUMP builder.
// These are compatibility evidence, NOT examples of valid new compilations.
// Never regenerate them with the current compiler or restore placeholder emission.
const bytes = {
    native: '',
    assembly: '',
    presentation: '',
};

module.exports = Object.freeze(Object.fromEntries(Object.entries(bytes).map(([name, encoded]) => {
    const buffer = Buffer.from(encoded, 'base64');
    if (buffer.length % 4) throw new Error('Invalid frozen LUMP length: ' + name);
    const words = Array.from({length: buffer.length / 4}, (_, i) => buffer.readUInt32BE(i * 4));
    return [name, Object.freeze(words)];
})));
